.version 8.0
.target sm_80
.address_size 64
.visible .entry positive_integer() {
  .reg .u16 %hu0, %hu1, %hu2, %hu3, %hud0, %hud1;
  .reg .s16 %hs0, %hs1, %hs2, %hs3, %hsd0, %hsd1;
  .reg .u32 %u0, %u1, %u2, %u3, %u4, %u5, %u6, %u7, %u8, %u9;
  .reg .s32 %s0, %s1, %s2, %s3, %s4, %s5, %s6, %s7, %s8, %s9;
  .reg .u64 %ud0, %ud1, %ud2, %ud3, %ud4, %ud5;
  .reg .s64 %sd0, %sd1, %sd2, %sd3, %sd4, %sd5;

  mul24.lo.u32 %u0, %u1, %u2;
  mul24.hi.u32 %u3, %u1, %u2;
  mul24.lo.s32 %s0, %s1, %s2;
  mul24.hi.s32 %s3, %s1, %s2;
  mad24.lo.u32 %u4, %u1, %u2, %u3;
  mad24.hi.u32 %u5, %u1, %u2, %u3;
  mad24.lo.s32 %s4, %s1, %s2, %s3;
  mad24.hi.s32 %s5, %s1, %s2, %s3;
  mad24.hi.sat.s32 %s6, %s1, %s2, %s3;

  mad.lo.u16 %hu0, %hu1, %hu2, %hu3;
  mad.hi.s16 %hs0, %hs1, %hs2, %hs3;
  mad.wide.u16 %u6, %hu1, %hu2, %u7;
  mad.wide.s16 %s7, %hs1, %hs2, %s8;
  mad.lo.u32 %u8, %u1, %u2, %u3;
  mad.hi.s32 %s8, %s1, %s2, %s3;
  mad.wide.u32 %ud0, %u1, %u2, %ud1;
  mad.wide.s32 %sd0, %s1, %s2, %sd1;

  sad.u16 %hu1, %hu2, %hu3, %hu0;
  sad.s16 %hs1, %hs2, %hs3, %hs0;
  sad.u32 %u0, %u1, %u2, %u3;
  sad.s32 %s0, %s1, %s2, %s3;
  sad.u64 %ud2, %ud3, %ud4, %ud5;
  sad.s64 %sd2, %sd3, %sd4, %sd5;

  fns.b32 %u0, %u1, 0, 1;
  fns.b32 %u2, %u1, 31, -1;
  fns.b32 %u3, %u1, %u2, %s2;

  szext.clamp.u32 %u4, %u1, %u2;
  szext.wrap.u32 %u5, %u1, %u2;
  szext.clamp.s32 %s4, %s1, %u2;
  szext.wrap.s32 %s5, %s1, %u2;
  szext.wrap.u32 %u6, 0xffffffff, 0;

  bmsk.clamp.b32 %u7, %u1, %u2;
  bmsk.wrap.b32 %u8, %u1, %u2;
  bmsk.wrap.b32 %u9, 1, 2;

  dp4a.u32.u32 %u0, %u1, %u2, %u3;
  dp4a.u32.s32 %s0, %u1, %s1, %s2;
  dp4a.s32.u32 %s3, %s1, %u2, %s2;
  dp4a.s32.s32 %s4, %s1, %s2, %s3;
  dp2a.lo.u32.u32 %u5, %u1, %u2, %u3;
  dp2a.lo.u32.s32 %s5, %u1, %s1, %s2;
  dp2a.hi.s32.u32 %s6, %s1, %u2, %s2;
  dp2a.hi.s32.s32 %s7, %s1, %s2, %s3;

  ret;
}

.version 8.0
