  neg.f16x2 %b0, %b1;
  abs.f16x2 %b2, %b3;
  abs.bf16x2 %b4, %b5;
  min.f16x2 %b6, %b7, %b8;
  min.NaN.f16x2 %b6, %b7, %b8;
  max.f16x2 %b6, %b7, %b8;
  max.NaN.f16x2 %b6, %b7, %b8;
  min.bf16x2 %b9, %b10, %b11;
  min.NaN.bf16x2 %b9, %b10, %b11;
  max.bf16x2 %b9, %b10, %b11;
  max.NaN.bf16x2 %b9, %b10, %b11;
  abs.f16 %h0, %h1;
  abs.bf16 %bh0, %bh1;
  neg.f16 %h0, %h1;
  min.f16 %h0, %h1, %h2;
  max.f16 %h0, %h1, %h2;
  min.bf16 %bh0, %bh1, %bh2;
  max.bf16 %bh0, %bh1, %bh2;
